#include <stdio.h>
#define MAX 5

int stack[MAX], top = -1;

void push(int x)
{
    if (top == MAX - 1) {
        printf("Stack Overflow\n");
        return;
    }
    stack[++top] = x;
    printf("%d pushed\n", x);
}

int pop(void)
{
    if (top == -1) {
        printf("Stack Underflow\n");
        return -1;
    }
    return stack[top--];
}

void peek(void)
{
    if (top == -1)
        printf("Stack is empty\n");
    else
        printf("Top = %d\n", stack[top]);
}

void display(void)
{
    int i;
    if (top == -1) {
        printf("Stack is empty\n");
        return;
    }
    printf("Stack (top to bottom): ");
    for (i = top; i >= 0; i--)
        printf("%d ", stack[i]);
    printf("\n");
}

int main(void)
{
    int ch, x;
    do {
        printf("1.Push 2.Pop 3.Peek");
        printf(" 4.Show 5.Exit: ");
        scanf("%d", &ch);
        switch (ch) {
        case 1:
            printf("Value: ");
            scanf("%d", &x);
            push(x);
            break;
        case 2:
            x = pop();
            if (x != -1)
                printf("Popped %d\n", x);
            break;
        case 3: peek(); break;
        case 4: display(); break;
        }
    } while (ch != 5);
    return 0;
}

#include <stdio.h>
#define MAX 3

int s[MAX], top = -1;

int push(int x)
{
    if (top == MAX - 1)
        return 0;             // overflow
    s[++top] = x;
    return 1;
}

int pop(int *x)
{
    if (top == -1)
        return 0;             // underflow
    *x = s[top--];
    return 1;
}

