#include <stdio.h>

char st[50];
int top = -1;

int match(char open, char close)
{
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

int balanced(char *e)
{
    int i;
    top = -1;
    for (i = 0; e[i] != '\0'; i++) {
        char c = e[i];
        if (c=='('||c=='['||c=='{')
            st[++top] = c;        // push
        else if (c==')'||c==']'||c=='}') {
            if (top == -1)
                return 0;
            if (!match(st[top--], c))
                return 0;
        }
    }
    // empty?
    return top == -1;
}

int main(void)
{
    char *t[] = {"{a+[b*(c-d)]}",
                 "(a+b]*c",
                 "((a+b)*c",
                 "[(x)]{y}"};
    int i;
    for (i = 0; i < 4; i++)
        printf("%-15s %s\n", t[i],
               balanced(t[i]) ? "Balanced"
                              : "Not OK");
    return 0;
}

#include <stdio.h>
#include <ctype.h>

char st[50];
int top = -1;

int prec(char c)
{
    if (c == '^') return 3;
    if (c=='*'||c=='/'||c=='%') return 2;
    if (c=='+'||c=='-') return 1;
    return 0;                   // '('
}

int main(void)
{
    char in[50], out[50], c;
    int i, k = 0;

    printf("Infix: ");
    scanf("%49s", in);
    for (i = 0; (c = in[i]) != '\0'; i++) {
        if (isalnum((unsigned char)c))
            // operand
            out[k++] = c;
        else if (c == '(')
            st[++top] = c;
        else if (c == ')') {
            while (st[top] != '(')
                out[k++] = st[top--];
            // drop '('
            top--;
        // operator
        } else {
            while (top != -1 &&
                (prec(st[top]) > prec(c) ||
                 (prec(st[top]) == prec(c)
                  && c != '^')))
                out[k++] = st[top--];
            st[++top] = c;
        }
    }
    while (top != -1)
        out[k++] = st[top--];
    out[k] = '\0';
    printf("Postfix: %s\n", out);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int st[50], top = -1;

int main(void)
{
    char e[50], c;
    int i, a, b, r;

    printf("Postfix (single digits): ");
    scanf("%49s", e);
    for (i = 0; (c = e[i]) != '\0'; i++) {
        if (isdigit((unsigned char)c))
            // push
            st[++top] = c - '0';
        else {
            b = st[top--];       // 2nd
            a = st[top--];       // 1st
            switch (c) {
            case '+': r = a + b; break;
            case '-': r = a - b; break;
            case '*': r = a * b; break;
            case '/': r = a / b; break;
            default:  r = 0;
            }
            printf("%d %c %d = %d\n",
                   a, c, b, r);
            st[++top] = r;
        }
    }
    printf("Result = %d\n", st[top]);
    return 0;
}

#include <stdio.h>

long fact(int n)
{
    long r;
    printf("call fact(%d)\n", n);
    if (n <= 1)
        r = 1;                // base case
    else
        r = n * fact(n - 1);  // recursive
    printf("fact(%d) returns %ld\n", n, r);
    return r;
}

int main(void)
{
    int n;
    printf("Enter n: ");
    scanf("%d", &n);
    printf("%d! = %ld\n", n, fact(n));
    return 0;
}

#include <stdio.h>

int gcd(int a, int b)
{
    printf("gcd(%d, %d)\n", a, b);
    if (b == 0)
        return a;             // base case
    return gcd(b, a % b);
}

int main(void)
{
    int a, b, g;
    printf("Enter two numbers: ");
    scanf("%d %d", &a, &b);
    g = gcd(a, b);
    printf("GCD = %d\n", g);
    printf("LCM = %d\n", a / g * b);
    return 0;
}

#include <stdio.h>

int calls = 0;

int fib(int n)
{
    calls++;
    if (n == 0) return 0;     // base cases
    if (n == 1) return 1;
    return fib(n - 1) + fib(n - 2);
}

int main(void)
{
    int n, i;
    printf("How many terms? ");
    scanf("%d", &n);
    printf("Series: ");
    for (i = 0; i < n; i++)
        printf("%d ", fib(i));
    printf("\n");

    calls = 0;
    printf("fib(10) = %d", fib(10));
    printf(" using %d calls\n", calls);
    return 0;
}

