#include <stdio.h>
#define MAX 4

int q[MAX], front = -1, rear = -1;

void insert(int x)
{
    if ((rear + 1) % MAX == front) {
        printf("Insert %d: Full\n", x);
        return;
    }
    if (front == -1)
        front = 0;
    // wrap
    rear = (rear + 1) % MAX;
    q[rear] = x;
    printf("Insert %d at [%d]\n", x, rear);
}

void delete(void)
{
    if (front == -1) {
        printf("Queue Empty\n");
        return;
    }
    printf("Delete %d from [%d]\n",
           q[front], front);
    if (front == rear)
        // now empty
        front = rear = -1;
    else
        front = (front + 1) % MAX;
}

void display(void)
{
    int i = front;
    if (front == -1) {
        printf("Queue Empty\n");
        return;
    }
    printf("Queue: ");
    while (1) {
        printf("%d ", q[i]);
        if (i == rear)
            break;
        i = (i + 1) % MAX;
    }
    printf("(F=%d R=%d)\n", front, rear);
}

int main(void)
{
    insert(10); insert(20);
    insert(30); insert(40);
    // full
    insert(50);
    delete(); delete();
    // wrap
    insert(50); insert(60);
    display();
    return 0;
}

#include <stdio.h>

int st[32], top = -1;

int main(void)
{
    int n, m;
    printf("Enter a decimal number: ");
    scanf("%d", &n);
    m = n;
    if (m == 0)
        st[++top] = 0;
    while (m > 0) {
        // remainder
        st[++top] = m % 2;
        m = m / 2;
    }
    printf("Binary of %d = ", n);
    while (top != -1)
        // reverse
        printf("%d", st[top--]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
#define MAX 5

char q[MAX][20];
int front = 0, rear = -1;

void add(char *name)
{
    if (rear == MAX - 1) {
        printf("Line is full\n");
        return;
    }
    strcpy(q[++rear], name);
    printf("%s joined the line\n", name);
}

void serve(void)
{
    if (front > rear) {
        printf("No one in line\n");
        return;
    }
    printf("Serving %s\n", q[front++]);
}

void search(char *name)
{
    int i;
    for (i = front; i <= rear; i++)
        if (strcmp(q[i], name) == 0) {
            printf("%s is at place %d\n",
                   name, i - front + 1);
            return;
        }
    printf("%s is not in line\n", name);
}

int main(void)
{
    add("Ravi"); add("Meena"); add("Amit");
    search("Amit");
    serve();
    search("Amit");
    search("Ravi");
    return 0;
}
